// --- CONFIGURABLE VARIABLES ---
const config = {
  githubRepo: $env.GITHUB_REPO || 'owner/repo',
  githubToken: $env.GITHUB_TOKEN || '',
  claudeApiKey: $env.CLAUDE_API_KEY || '',
  claudeModel: 'claude-sonnet-4-20250514',
  language: $env.LANGUAGE || 'en',
  deliveryMethod: $env.DELIVERY_METHOD || 'webhook',
  webhookUrl: $env.WEBHOOK_URL || '',
};

// Calculate date range (past 7 days)
const now = new Date();
const weekAgo = new Date(now);
weekAgo.setDate(now.getDate() - 7);

const since = weekAgo.toISOString().split('T')[0];
const until = now.toISOString().split('T')[0];
const langName = config.language === 'zh' ? 'Chinese' : 'English';

return [{
  json: {
    ...config,
    since,
    until,
    langName,
    repoUrl: `https://api.github.com/repos/${config.githubRepo}`,
  }
}];

// Filter merged PRs (GitHub API doesn't have a 'merged' filter)
const allItems = [];
for (const item of $input.all()) {
  if (item.json.merged_at) {
    allItems.push(item);
  }
}
return allItems;

// Combine all data for Claude prompt
const commits = $('Fetch Commits').first().json || [];
const issues = $('Fetch Closed Issues').first().json || [];
const mergedPRs = $('Filter Merged PRs').first().json || [];

const config = $('Set Config').first().json;
const repo = config.githubRepo;
const lang = config.langName;
const since = config.since;
const until = config.until;

// Build structured summary
let commitList = (Array.isArray(commits) ? commits : []).slice(0, 50).map(c =>
  `- ${c.commit?.message?.split('\n')[0] || 'no message'} (${c.author?.login || c.commit?.author?.name || 'unknown'})`
).join('\n');

let issueList = (Array.isArray(issues) ? issues : []).filter(i => i.pull_request === undefined).slice(0, 50).map(i =>
  `- #${i.number}: ${i.title} (${i.state})`
).join('\n');

let prList = (Array.isArray(mergedPRs) ? mergedPRs : []).slice(0, 50).map(pr =>
  `- #${pr.number}: ${pr.title} by ${pr.user?.login || 'unknown'}`
).join('\n');

const prompt = `You are a technical writer. Write a weekly development summary for GitHub repo "${repo}".

Period: ${since} to ${until}
Language: ${lang}

This week's activity:

**Commits** (${(Array.isArray(commits) ? commits : []).length} total):
${commitList || 'No commits found.'}

**Closed Issues** (${(Array.isArray(issues) ? issues : []).filter(i => i.pull_request === undefined).length} total):
${issueList || 'No closed issues found.'}

**Merged Pull Requests** (${(Array.isArray(mergedPRs) ? mergedPRs : []).length} total):
${prList || 'No merged PRs found.'}

Write a narrative summary with these sections:
1. **Overview** — 2-3 sentences on the week's main focus
2. **Key Changes** — bullet list of important work
3. **Notable PRs** — highlight interesting merges
4. **Activity Stats** — commit count, issues closed, PRs merged

Keep it engaging, not robotic. Use markdown formatting.`;

return [{ json: { prompt, repo, since, until } }];

// Extract summary text from Claude response
const claudeResp = $('Call Claude API').first().json;
const summary = claudeResp.content?.[0]?.text || 'No summary generated.';
const repo = $('Set Config').first().json.githubRepo;
const since = $('Set Config').first().json.since;
const until = $('Set Config').first().json.until;

return [{
  json: {
    summary,
    repo,
    period: `${since} to ${until}`,
    webhookUrl: $('Set Config').first().json.webhookUrl,
    deliveryMethod: $('Set Config').first().json.deliveryMethod,
  }
}];

// Log output for testing/debugging
const summary = $('Extract Summary').first().json;
console.log('=== WEEKLY DEV SUMMARY ===');
console.log(`Repo: ${summary.repo}`);
console.log(`Period: ${summary.period}`);
console.log(summary.summary);

return [{ json: { status: 'success', ...summary } }];
